#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

/**
 * Problem: 10602 - Longest Paths
 * 
 * 解題思路：
 * 1. 給定一個有向無環圖 (DAG) 和起始點 S。
 * 2. 尋找從 S 出發的最長路徑及其終點。
 * 3. 由於是 DAG，可以使用動態規劃 (DP) 或記憶化搜尋解決。
 * 4. 令 dp[i] 為從節點 i 出發的最長路徑長度，
 *    dp[i] = 1 + max(dp[j]) 對於所有 i -> j 的邊。
 */

int n, s;
vector<int> adj[101];
int memo[101];
int next_node[101];

int solve(int u) {
    if (memo[u] != -1) return memo[u];

    int max_len = 0;
    int best_v = -1;

    for (int v : adj[u]) {
        int len = 1 + solve(v);
        if (len > max_len) {
            max_len = len;
            best_v = v;
        } else if (len == max_len) {
            if (best_v == -1 || v < best_v) {
                best_v = v;
            }
        }
    }

    next_node[u] = best_v;
    return memo[u] = max_len;
}

int main() {
    int caseNum = 1;
    while (cin >> n && n != 0) {
        cin >> s;
        for (int i = 1; i <= n; ++i) {
            adj[i].clear();
            memo[i] = -1;
        }

        int u, v;
        while (cin >> u >> v && (u != 0 || v != 0)) {
            adj[u].push_back(v);
        }

        int max_len = solve(s);
        int target = s;
        while (next_node[target] != -1) {
            target = next_node[target];
        }

        cout << "Case " << caseNum++ << ": The longest path from " << s 
             << " has length " << max_len << ", finishing at " << target << "." << endl << endl;
    }
    return 0;
}
